                Assert.Equal(failing - 1, spy.Dispensed.Count);
                Assert.Equal(Sum(spy.Dispensed), result.Notes);
                Assert.Equal(stock - result.Notes, spy.Stock);
                Assert.Equal(0, result.Fee);
