            [
                (Full, null, NoteCounts.None, AtmStatus.InvalidAmount),
                (new(0, 0, 0), Denomination.Ten, new(0, 0, 1), AtmStatus.CassetteJammed),
                (new(5, 0, 0), null, new(1, 1, 1), AtmStatus.CassetteFull),
